	if (emptyBucket != null) {
		emptyBucket.clear();
	}
	for (int i = minLabel; i < labels.size(); i++) {
		Set<Integer> bucket = bucketsByLabel.getOrDefault(i, new HashSet<>());
		bucket.add(labels.get(i));
		bucketsByLabel.set(i, bucket);
	}
