    String[] pathParts = path.split("/");
    String[] relativePathParts = relativePath.split("/");
    int levelsUp = 0;
    for (String part : relativePathParts) {
        if (part.equals("..")) {
            levelsUp++;
        }
    }
    String[] finalPathParts = new String[pathParts.length - levelsUp];
    for (int i = 0; i < finalPathParts.length; i++) {
        finalPathParts[i] = pathParts[i + levelsUp];
    }
    StringBuilder builder = new StringBuilder();
    for (int i = 0; i < finalPathParts.length; i++) {
        if (i > 0) {
            builder.append("/");
        }
        builder.append(finalPathParts[i]);
    }
    return builder.toString();
}

