public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
	List<ThreadSnapshot> threadSnapshots = new ArrayList<>();

	try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
		String line = reader.readLine();
		while (line != null) {
			String[] tokens = line.split(",");
			if (tokens.length == 11) {
				long timestamp = Long.parseLong(tokens[0]);
				String threadName = tokens[1];
				long threadId = Long.parseLong(tokens[2]);
				int priority = Integer.parseInt(tokens[3]);
				boolean daemon = Boolean.parseBoolean(tokens[4]);
				boolean alive = Boolean.parseBoolean(tokens[5]);
				String state = tokens[6];
				long nativeThreadId = Long.parseLong(tokens[7]);
				String group = tokens[8];
				boolean isSharedClasLoader = Boolean.parseBoolean(tokens[9]);
				String contextClassloader = tokens[10];

				ThreadSnapshot threadSnapshot = new ThreadSnapshot(timestamp, threadName, threadId, priority, daemon, alive, state, nativeThreadId, group, isSharedClasLoader, contextClassloader);
				threadSnapshots.add(threadSnapshot);
			}
			line = reader.readLine();
		}
	}

	List<ThreadSnapshot> results = new ArrayList<>();
	for (ThreadSnapshot threadSnapshot : threadSnapshots) {
		if (timeRanges.stream().anyMatch(timeRange -> timeRange.contains(threadSnapshot.timestamp))) {
			results.add(threadSnapshot);
		}
	}

	return results;
}

