public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    // First, read the file and extract the thread snapshots
    List<ThreadSnapshot> snapshots = new ArrayList<>();
    try (BufferedReader br = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = br.readLine()) != null) {
            if (line.startsWith("Thread id=")) {
                // This is a new thread snapshot
                snashots.add(new ThreadSnapshot(line.split(" ")[2]));
            } else {
                // This is a method invocation
                StringTokenizer tok = new StringTokenizer(line, ";");
                String methodName = tok.nextToken();
                String threadId = tok.nextToken();
                snapshots.get(snapshots.size() - 1).addMethodCall(new MethodCall(methodName, threadId));
            }
        }
    }

    // Second, filter the snapshots based on the time ranges
    List<ThreadSnapshot> filteredSnapshots = new ArrayList<>();
    for (ProfileAnalyzeTimeRange range : timeRanges) {
        for (ThreadSnapshot snapshot : snapshots) {
            if (snapshot.getTid() >= range.getStartTime() && snapshot.getTid() <= range.getEndTime()) {
                filteredSnapshots.add(snapshot);
            }
        }
    }

    // Return the filtered snapshots
    return filteredSnapshots;
}

